package com.example.rokidgeminisecretary;
import android.content.*;import android.os.*;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import com.example.rokidkeyboardbridge.*;
/** Six-hour virtual trace plus 120 seconds of wall-clock policy/load checking; never live navigation/voice. */
public final class NavigationEnduranceChecks {
 static long heap(){Runtime r=Runtime.getRuntime();return r.totalMemory()-r.freeMemory();}
 public static JSONObject run(Context context)throws Exception{
 MainActivity owner=ReliabilityChecks.owner(context);JSONArray traceRoute=new JSONArray(),traceSteps=new JSONArray();for(int i=0;i<=100;i++)traceRoute.put(new JSONArray().put(0).put(i*.0001));for(double v:new double[]{.2,.5,.8})traceSteps.put(new JSONObject().put("progress",v).put("type","google").put("instruction",v==.5?"左折":"右折").put("distance",200).put("duration",60));int actualHudCalls=0;
 NavigationProgressLatch progress=new NavigationProgressLatch();NavigationGeometryCache geometry=new NavigationGeometryCache("[[0,0],[0,0.001],[0,0.002]]","[]");NavigationPositionRecovery recovery=new NavigationPositionRecovery();NavigationSpeechLane lane=new NavigationSpeechLane();NavigationVoiceSession voice=new NavigationVoiceSession();com.example.rokidkeyboardbridge.NavigationSmoothMetrics metrics=new com.example.rokidkeyboardbridge.NavigationSmoothMetrics();long virtual=100000;int sent=0;long simulationStart=SystemClock.elapsedRealtime();
 for(int i=0;i<21600;i++){long t=virtual+i*1000L;if(i%10==0){NavigationModeMatrixChecks.hud(owner,traceRoute,traceSteps,(i/10)%100,System.currentTimeMillis(),5,"virtual-hud-"+(i/1000));actualHudCalls++;}String route="synthetic-"+(i/600);boolean gap=i%600>=250&&i%600<280;double accuracy=gap?80:5;progress.accept(route,t,t,accuracy,(i%600)/600.0);boolean ready=recovery.accept(route,t,t,accuracy,40);if(i%100==0)voice.interrupt(t);boolean held=voice.held(t,i%50<3,i%80<4);long ticket=lane.offer(route,"合成の曲がり案内",i%20==0,t,false);if(ready&&!held&&lane.valid(ticket,route,t)){lane.complete(ticket);sent++;}if(gap)lane.clear();metrics.sample("uiWork",(long)(geometry.distance(0,2)*1000));if(i%600==0&&metrics.snapshot().getJSONObject("samples").getJSONObject("uiWork").getInt("count")>120)throw new AssertionError("unbounded metrics");}
 long simulationMs=SystemClock.elapsedRealtime()-simulationStart;System.gc();Thread.sleep(200);long before=heap(),started=SystemClock.elapsedRealtime(),maxHeap=before,maxUiWait=0;int ticks=0;NavigationLatestJob job=new NavigationLatestJob();AtomicInteger callbacks=new AtomicInteger();try{
 while(SystemClock.elapsedRealtime()-started<120000){long t=virtual+21600000+ticks*50L;if(ticks%10==0){NavigationModeMatrixChecks.hud(owner,traceRoute,traceSteps,ticks%100,System.currentTimeMillis(),5,"wall-hud-"+(ticks/200));actualHudCalls++;}String route="soak-"+(ticks/200);boolean ready=recovery.accept(route,t,t,ticks%100<5?80:5,40);long token=lane.offer(route,"合成案内",ticks%20==0,t,false);if(ready&&lane.valid(token,route,t))lane.complete(token);metrics.sample("uiQueue",1000);metrics.sample("speechWait",voice.held(t,ticks%10<2,ticks%40<4)?200000000:0);job.submit(()->{Thread.sleep(80);return 1;},(id,value,error)->callbacks.incrementAndGet());if(job.pending()>1||job.active()>2)throw new AssertionError("unbounded jobs");if(ticks%40==0){CountDownLatch heartbeat=new CountDownLatch(1);long posted=SystemClock.elapsedRealtime();new Handler(Looper.getMainLooper()).post(heartbeat::countDown);if(!heartbeat.await(2,TimeUnit.SECONDS))throw new AssertionError("UI heartbeat blocked");maxUiWait=Math.max(maxUiWait,SystemClock.elapsedRealtime()-posted);maxHeap=Math.max(maxHeap,heap());}ticks++;Thread.sleep(50);}
 }finally{job.close();}
 System.gc();Thread.sleep(200);long after=heap();if(after-before>32L*1024*1024)throw new AssertionError("retained heap growth exceeds 32MiB tolerance");return new JSONObject().put("actualHudInvocations",actualHudCalls).put("virtualTraceHours",6).put("virtualSamples",21600).put("virtualSimulationMs",simulationMs).put("virtualCueAdmissions",sent).put("wallClockSoakMs",SystemClock.elapsedRealtime()-started).put("wallClockTicks",ticks).put("heapBeforeBytes",before).put("heapAfterGcBytes",after).put("peakObservedHeapBytes",maxHeap).put("retainedHeapGrowthBytes",after-before).put("maxUiHeartbeatWaitMs",maxUiWait).put("maxWorkerCount",2).put("maxPendingCount",1).put("ringSampleLimit",120).put("scope","policy objects, six-hour virtual trace and 120-second wall-clock synthetic concurrent job/voice-hold simulation; no microphone, TTS, provider calls, live GPS or actual inter-device route traffic");
 }
}
